+    static void test_0() {
+        var a = new MyValue[10];
+        Object npe = null;
+        try {
+            System.arraycopy(null, 0, a, 1, 2);
+        } catch (NullPointerException e) {
+            npe = e;
+        }
+        Asserts.assertNotNull(npe, "Missing NullPointerException");
+    }
